const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state={companies:[],devices:[],logs:[],incidents:[],revision:0},view='Overview',company='All companies',query='',type='All types',busy=false;
async function api(path,method='GET',body){let r=await fetch(path,{method,headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});if(r.status===401){location.href='/login';throw Error('Sign in required.')}let data=r.status===204?{}:await r.json();if(!r.ok)throw Error(data.error||'Request failed.');return data}
function toast(s){$('#toast').textContent=s;$('#toast').classList.remove('hidden');clearTimeout(window.tt);window.tt=setTimeout(()=>$('#toast').classList.add('hidden'),6500)}
function modal(html){$('#drawer').innerHTML='<button class="close" onclick="closePanel()" aria-label="Close">✕</button>'+html;$('#drawer').classList.remove('hidden')}
function closePanel(){$('#drawer').classList.add('hidden')}
document.addEventListener('keydown',e=>{if(e.key==='Escape')closePanel()});
function ds(){return state.devices.filter(d=>company==='All companies'||d.company===company)}
function navigate(v){view=v;query='';type='All types';render()}
async function refresh(){state=await api('/api/state');if(company!=='All companies'&&!state.companies.includes(company))company='All companies';render()}
async function mutate(fn){if(busy)return toast('Please wait for the current save.');busy=true;let draft=structuredClone(state);try{fn(draft);state=await api('/api/state','PUT',draft);closePanel();render();toast('Saved to server.')}catch(e){toast(e.message);if(/another window/.test(e.message))await refresh()}finally{busy=false}}
function nav(){const items=['Overview','Devices','Companies','Alerts','Activity log','Settings'];$('#nav').innerHTML=items.map((v,i)=>`<button class="nav ${view===v?'active':''}" data-nav="${i}"><span>${['◫','▣','▦','♧','◷','⚙'][i]}</span>${v}</button>`).join('');document.querySelectorAll('[data-nav]').forEach(el=>el.onclick=()=>navigate(items[+el.dataset.nav]));$('#companynav').innerHTML=state.companies.map((c,i)=>`<div class="company" data-company="${i}"><span class="dot"></span>${esc(c)}</div>`).join('')||'<p class="metric-note">No companies yet</p>';document.querySelectorAll('[data-company]').forEach(el=>el.onclick=()=>{company=state.companies[+el.dataset.company];navigate('Overview')});$('#companyFilter').innerHTML=['All companies',...state.companies].map(c=>`<option ${company===c?'selected':''}>${esc(c)}</option>`).join('');$('#companyFilter').onchange=e=>{company=e.target.value;render()}}
function metric(v,suffix='%'){return v==null?'—':Number(v).toFixed(1)+suffix}
function age(t){if(!t)return 'Never reported';let seconds=Math.max(0,Math.round(Date.now()/1000-t));return seconds<60?seconds+'s ago':seconds<3600?Math.floor(seconds/60)+'m ago':Math.floor(seconds/3600)+'h ago'}
function duration(s){if(s==null)return '—';return Math.floor(s/86400)+'d '+Math.floor(s%86400/3600)+'h '+Math.floor(s%3600/60)+'m'}
function stats(){let devices=ds();return `<div class="stats">${[['Total devices',devices.length,'Across '+(company==='All companies'?state.companies.length:1)+' companies'],['Online',devices.filter(d=>['Online','Warning'].includes(d.status)).length,'Reporting within 3 minutes'],['Active alerts',state.incidents.filter(i=>devices.some(d=>d.id===i.device)).length,'Open monitoring incidents'],['Awaiting agent',devices.filter(d=>d.status==='Pending').length,'Enroll an agent to start']].map((s,i)=>`<div class="card stat"><span style="color:#7e899e">${s[0]}</span><div class="big ${i===1?'green':i===2?'amber':''}">${s[1]}</div><small>${s[2]}</small></div>`).join('')}</div>`}
function table(){return `<section class="card"><div class="cardhead"><h2>Devices</h2><span class="metric-note">${ds().length} total</span></div><div class="filters"><input id="search" class="search" aria-label="Search devices" placeholder="Search name, IP, or platform…" value="${esc(query)}"><select id="typeFilter" aria-label="Device type">${['All types','Server','Router','Switch','Storage','Access point'].map(t=>`<option ${type===t?'selected':''}>${t}</option>`).join('')}</select></div><div class="tablewrap"><table><thead><tr><th>DEVICE</th><th>STATUS</th><th>CPU / MEMORY</th><th>DISK</th><th>LAST REPORT</th></tr></thead><tbody id="rows"></tbody></table></div><div class="tablefoot">Select a device to view metrics, history, and connection settings.</div></section>`}
function rows(){let devices=ds().filter(d=>(type==='All types'||d.type===type)&&[d.name,d.ip,d.platform].join(' ').toLowerCase().includes(query.toLowerCase()));$('#rows').innerHTML=devices.map(d=>`<tr tabindex="0" role="button" data-device="${d.id}"><td><div class="device-name">${esc(d.name)}</div><div class="device-sub">${esc(d.ip)} · ${esc(d.platform)}</div></td><td><span class="badge ${d.status.toLowerCase()}">${esc(d.status)}</span></td><td>${metric(d.cpu)} / ${metric(d.memory)}</td><td>${metric(d.disk)}</td><td>${age(d.lastSeen)}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">No devices found. Add a company and device to begin.</td></tr>';document.querySelectorAll('[data-device]').forEach(el=>{el.onclick=()=>detail(+el.dataset.device);el.onkeydown=e=>{if(e.key==='Enter')el.click()}})}
function alerts(){let devices=ds(),items=state.incidents.filter(i=>devices.some(d=>d.id===i.device));return items.map(i=>{let d=devices.find(d=>d.id===i.device);return `<div class="alert"><span class="eventdot"></span><div><strong>${esc(i.message)}</strong><p>${esc(d.name)} · ${esc(d.company)}</p><small>Opened ${esc(new Date(i.opened*1000).toLocaleString())}</small></div></div>`}).join('')||'<div class="empty">No open incidents.</div>'}
function side(){return `<div class="right"><section class="card"><div class="cardhead"><h2>Needs attention</h2></div>${alerts()}</section><section class="card"><div class="cardhead"><h2>Monitoring</h2></div><div class="health"><p>Linux agents report CPU, memory, disk usage, and uptime every minute.</p><p class="metric-note">An incident opens when an agent stops reporting for 3 minutes or resource usage exceeds 90%. Recovery closes the incident automatically.</p></div></section></div>`}
function render(){nav();$('#breadcrumb').textContent=view;$('#title').textContent=view==='Overview'?'Infrastructure overview':view;$('#subtitle').textContent=({Overview:'Your infrastructure, in one clear view.',Devices:'Inventory and live agent measurements.',Companies:'Organize infrastructure by customer.',Alerts:'Current incidents and recovery history.','Activity log':'Server-recorded changes and monitoring events.',Settings:'Account, agent setup, and inventory backups.'})[view];$('#addDevice').onclick=()=>editDevice();let html='';if(view==='Overview')html=stats()+`<div class="grid">${table()}${side()}</div>`;if(view==='Devices')html=stats()+table();if(view==='Companies')html=`<button class="btn primary section" onclick="editCompany()">＋ Add company</button><div class="companycards">${state.companies.map((c,i)=>`<section class="card"><h2>${esc(c)}</h2><p>${state.devices.filter(d=>d.company===c).length} devices</p><button class="btn" data-edit-company="${i}">Edit company</button></section>`).join('')||'<div class="empty">No companies yet.</div>'}</div>`;if(view==='Alerts')html=`<div class="grid section"><section class="card"><div class="cardhead"><h2>Open incidents</h2></div>${alerts()}</section><section class="card"><div class="cardhead"><h2>Active monitoring rules</h2></div><div class="health"><p>Agent missing: no report for 3 minutes.</p><p>High resource usage: CPU, memory, or disk above 90%.</p><p class="metric-note">Incidents are visible here and in the activity log. External notification delivery is not configured.</p></div></section></div>`;if(view==='Activity log')html=`<section class="card section"><div class="cardhead"><h2>Activity</h2><button class="btn" onclick="exportLogs()">Export CSV</button></div><div class="tablewrap"><table><thead><tr><th>TIME</th><th>ACTION</th><th>DEVICE / DETAIL</th></tr></thead><tbody>${state.logs.map(l=>`<tr><td>${esc(l.time)}</td><td>${esc(l.action)}</td><td>${esc(l.device)}</td></tr>`).join('')||'<tr><td colspan="3" class="empty">No activity yet.</td></tr>'}</tbody></table></div></section>`;if(view==='Settings')html=`<div class="companycards"><section class="card"><h2>Administrator account</h2><p>Change your sign-in password. Other sessions will be signed out.</p><button class="btn" onclick="passwordForm()">Change password</button></section><section class="card"><h2>Inventory backup</h2><p>Export companies and inventory. Agent credentials and metric history stay on the server.</p><a class="btn" href="/api/backup">Download inventory</a><p><button class="btn" onclick="importInventory()">Import inventory</button></p></section><section class="card"><h2>Linux monitoring agent</h2><p>Open a device and select Connect agent to get its installation instructions. Each device has its own revocable credential.</p><p class="metric-note">Reboot, firmware, PoE, Proxmox API, and device configuration actions are not available in this release.</p></section></div>`;$('#page').innerHTML=html;if($('#rows')){rows();$('#search').oninput=e=>{query=e.target.value;rows()};$('#typeFilter').onchange=e=>{type=e.target.value;rows()}}document.querySelectorAll('[data-edit-company]').forEach(el=>el.onclick=()=>editCompany(+el.dataset.editCompany))}
function editCompany(index=null){let old=index===null?'':state.companies[index];modal(`<h1>${old?'Edit':'Add'} company</h1><form id="companyForm"><label class="formlabel" for="companyName">Company name</label><input id="companyName" class="field" required maxlength="128" value="${esc(old)}"><div class="actions"><button class="btn primary">Save company</button>${old?'<button class="btn" type="button" id="deleteCompany">Delete company</button>':''}</div></form>`);$('#companyForm').onsubmit=e=>{e.preventDefault();let name=$('#companyName').value.trim();if(state.companies.some(c=>c!==old&&c.toLowerCase()===name.toLowerCase()))return toast('This company already exists.');mutate(s=>{if(old){s.companies[index]=name;s.devices.forEach(d=>{if(d.company===old)d.company=name})}else s.companies.push(name)})};if(old)$('#deleteCompany').onclick=()=>{if(state.devices.some(d=>d.company===old))return toast('Move or delete this company’s devices first.');if(confirm('Delete this company?'))mutate(s=>{s.companies.splice(index,1)})}}
function editDevice(id){if(!state.companies.length)return editCompany();let d=state.devices.find(x=>x.id===id)||{name:'',company:company==='All companies'?state.companies[0]:company,type:'Server',ip:'',platform:'Ubuntu Linux',port:22};modal(`<h1>${id?'Edit':'Add'} device</h1><form id="deviceForm"><label class="formlabel" for="name">Device name</label><input id="name" class="field" name="name" required maxlength="128" value="${esc(d.name)}"><label for="deviceCompany">Company</label><select id="deviceCompany" class="field" name="company">${state.companies.map(c=>`<option ${d.company===c?'selected':''}>${esc(c)}</option>`).join('')}</select><label for="deviceType">Device type</label><select id="deviceType" class="field" name="type">${['Server','Router','Switch','Storage','Access point'].map(t=>`<option ${t===d.type?'selected':''}>${t}</option>`).join('')}</select><label for="ip">Management IP or hostname</label><input id="ip" class="field" name="ip" required maxlength="253" value="${esc(d.ip)}"><label for="platform">Platform / model</label><input id="platform" class="field" name="platform" required maxlength="128" value="${esc(d.platform)}"><label for="port">Connection check port</label><input id="port" class="field" name="port" type="number" min="1" max="65535" required value="${d.port||22}"><p class="metric-note">Inventory entries remain pending until their agent reports metrics.</p><button class="btn primary">Save device</button></form>`);$('#deviceForm').onsubmit=e=>{e.preventDefault();let values=Object.fromEntries(new FormData(e.target));values.port=+values.port;mutate(s=>{if(id){Object.assign(s.devices.find(d=>d.id===id),values)}else{s.devices.push({...values,id:Date.now()})}})}}
async function detail(id){let d=state.devices.find(d=>d.id===id);if(!d)return;modal(`<span class="badge ${d.status.toLowerCase()}">${esc(d.status)}</span><h1 class="section">${esc(d.name)}</h1><p>${esc(d.company)} · ${esc(d.platform)}<br>${esc(d.ip)}</p><div class="detailgrid">${[['CPU',metric(d.cpu)],['Memory',metric(d.memory)],['Disk',metric(d.disk)],['Uptime',duration(d.uptimeSeconds)]].map(m=>`<div class="card"><small>${m[0]}</small><strong>${m[1]}</strong></div>`).join('')}</div><p class="metric-note">Last report: ${age(d.lastSeen)}</p><div class="actions"><button class="btn" onclick="editDevice(${id})">Edit device</button><button class="btn primary" onclick="enroll(${id})">Connect agent</button><button class="btn" onclick="checkDevice(${id})">Test connection</button><button class="btn" onclick="removeDevice(${id})">Delete</button></div><h2 class="section">CPU history</h2><div id="history" class="empty">Loading measurements…</div><p class="metric-note">Agent measurements are retained for 30 days. History shows the latest 100 reports.</p>`);try{let samples=await api('/api/history/'+id);if(!$('#history'))return;if(!samples.length){$('#history').textContent='No measurements yet. Connect an agent to begin.';return}let values=samples.slice().reverse().filter(x=>x.cpu!=null);if(!values.length){$('#history').textContent='No CPU measurements yet.';return}let points=values.map((x,i)=>`${values.length===1?150:i/(values.length-1)*300},${80-x.cpu*.75}`).join(' ');$('#history').innerHTML=`<svg class="spark" viewBox="0 0 300 90" role="img" aria-label="Measured CPU usage"><polyline points="${points}" fill="none" stroke="#4367e9" stroke-width="2"/></svg><span class="metric-note">${esc(new Date(values[0].time*1000).toLocaleTimeString())} — ${esc(new Date(values.at(-1).time*1000).toLocaleTimeString())}</span>`}catch(e){toast(e.message)}}
function removeDevice(id){if(confirm('Delete this device, its agent credential, metrics, and incidents?'))mutate(s=>{s.devices=s.devices.filter(d=>d.id!==id)})}
async function checkDevice(id){try{let r=await api('/api/check','POST',{id});toast(r.reachable?`Connection successful on port ${r.port} (${r.latencyMs} ms). This does not enroll an agent.`:`Cannot connect on port ${r.port}. Check the device and network.`)}catch(e){toast(e.message)}}
async function enroll(id){if(!confirm('Generate a new agent credential? Any existing agent for this device will need the new credential.'))return;try{let r=await api('/api/enroll','POST',{id});modal('<h1>Connect Linux agent</h1><p>Run these commands as root inside the Linux device you selected. The credential is shown once and grants permission to submit metrics for this device only.</p><pre id="installCommand"></pre><button class="btn" id="copyInstall">Copy commands</button><p class="metric-note">Reports start within a minute. The agent only reads metrics; it does not execute device control commands. Use this HTTP endpoint only on your trusted network; remote deployments need HTTPS.</p>');let config=JSON.stringify({server:location.origin,token:r.token,interval:60});let command=`install -d -m 755 /opt/bitwise-agent\npython3 -c 'from urllib.request import urlretrieve; urlretrieve("${location.origin}/agent.py", "/opt/bitwise-agent/agent.py")'\ncat > /etc/bitwise-agent.json <<'CONFIG'\n${config}\nCONFIG\nchmod 600 /etc/bitwise-agent.json\ncat > /etc/systemd/system/bitwise-agent.service <<'SERVICE'\n[Unit]\nDescription=Bitwise Control Linux monitoring agent\nAfter=network-online.target\nWants=network-online.target\n[Service]\nExecStart=/usr/bin/python3 /opt/bitwise-agent/agent.py\nRestart=always\nRestartSec=15\nNoNewPrivileges=yes\nProtectSystem=strict\nProtectHome=yes\nPrivateTmp=yes\n[Install]\nWantedBy=multi-user.target\nSERVICE\nsystemctl daemon-reload\nsystemctl enable --now bitwise-agent`;$('#installCommand').textContent=command;$('#copyInstall').onclick=async()=>{try{await navigator.clipboard.writeText(command);toast('Commands copied.')}catch{toast('Select and copy the commands above.')}}}catch(e){toast(e.message)}}
function passwordForm(){modal('<h1>Change password</h1><form id="passwordForm"><label class="formlabel" for="currentPassword">Current password</label><input id="currentPassword" class="field" type="password" name="current" autocomplete="current-password" required><label for="newPassword">New password</label><input id="newPassword" class="field" type="password" name="password" autocomplete="new-password" minlength="12" maxlength="1024" required><label for="confirmPassword">Confirm new password</label><input id="confirmPassword" class="field" type="password" autocomplete="new-password" required><button class="btn primary">Change password</button></form>');$('#passwordForm').onsubmit=async e=>{e.preventDefault();if($('#newPassword').value!==$('#confirmPassword').value)return toast('Passwords do not match.');try{await api('/api/password','POST',Object.fromEntries(new FormData(e.target)));closePanel();toast('Password changed.')}catch(e){toast(e.message)}}}
function exportLogs(){let csv=[['Time','Action','Device'],...state.logs.map(l=>[l.time,l.action,l.device])].map(r=>r.map(v=>'"'+String(v).replace(/^[=+@-]/,"'$&").replace(/"/g,'""')+'"').join(',')).join('\r\n');let a=document.createElement('a'),url=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.href=url;a.download='bitwise-activity.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function importInventory(){let input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=async()=>{try{let file=input.files[0];if(file.size>2000000)throw Error('Inventory file is too large.');let data=JSON.parse(await file.text());if(!Array.isArray(data.companies)||!Array.isArray(data.devices))throw Error('Invalid inventory backup.');if(confirm('Replace your inventory with this backup? Removed devices will lose their agent credentials and history.'))await mutate(s=>{s.companies=data.companies;s.devices=data.devices})}catch(e){toast(e.message)}};input.click()}
async function boot(){try{await refresh();let old;try{old=JSON.parse(sessionStorage.getItem('bitwise-control-clean-v2'))}catch{}if(old?.devices?.length&&!state.devices.length){if(confirm('Import the devices you previously added in this browser into the server database?')){await mutate(s=>{s.companies=old.companies;s.devices=old.devices.map(d=>({...d,port:d.port||22}))});if(state.devices.length)sessionStorage.removeItem('bitwise-control-clean-v2')}}localStorage.removeItem('bitwise-control-v1')}catch(e){toast(e.message)}}
setInterval(async()=>{if(busy||!$('#drawer').classList.contains('hidden')||document.activeElement?.tagName==='INPUT')return;try{await refresh()}catch(e){toast(e.message)}},30000);boot();
